import { readFileSync } from 'node:fs';
import { describe, it, expect } from 'vitest';
import type { ModeDef, ModeModifier } from '../src/rules/types';

/*
 * MODES vs PRINT — the 115 findings of the 2026-09-15 modes audit, one leg each.
 *
 * Every leg reads a SEED file, never public/core.json. That is the whole point: core.json is
 * regenerated by `npm run data` from these three sources, so a leg that read the generated copy
 * would pass on a file that the next regen throws away. Proving the SOURCE proves the ship.
 *
 *   scripts/data/consumable-modes.json  item modes (an array)
 *   scripts/data/toggle-modes.json      everything else (an id-keyed object)
 *   scripts/data/effect-backfill.json   three records that exist ONLY as overlay rows
 *
 * Each finding was adversarially confirmed against the printed text (live Archives where the local
 * prose is scrape-damaged) before it reached here. Legs marked `it.todo` are the findings whose fix
 * needs a change outside this lane — they are named so the count stays honest, not silently dropped.
 */

const consumable = JSON.parse(readFileSync('scripts/data/consumable-modes.json', 'utf8')) as ModeDef[];
const toggle = JSON.parse(readFileSync('scripts/data/toggle-modes.json', 'utf8')) as Record<string, ModeDef>;

/** An item mode by id, from the array file. Throws rather than returning undefined so a renamed
 *  record fails loudly instead of every expect silently reading `undefined`. */
function item(id: string): ModeDef {
  const m = consumable.find((x) => x.id === id);
  if (!m) throw new Error(`no item mode "${id}" in scripts/data/consumable-modes.json`);
  return m;
}

function mode(id: string): ModeDef {
  const m = toggle[id];
  if (!m) throw new Error(`no toggle mode "${id}" in scripts/data/toggle-modes.json`);
  return m;
}

const mods = (m: ModeDef): ModeModifier[] => m.modifiers ?? [];
/** The first modifier on `target` (optionally narrowed by `detail`). */
const modFor = (m: ModeDef, target: string, detail?: string): ModeModifier | undefined =>
  mods(m).find((x) => x.target === target && (detail === undefined || x.detail === detail));

/** The overlay row that CREATES a mode — for the three records with no seed-file entry. */
let overlayCache: { category: string; id: string; field?: string; create?: boolean; value?: unknown }[] | null = null;
function overlayRows() {
  overlayCache ??= JSON.parse(readFileSync('scripts/data/effect-backfill.json', 'utf8')) as typeof overlayCache;
  return overlayCache!;
}
function overlayMode(id: string): ModeDef {
  const row = overlayRows().find((r) => r.category === 'modes' && r.id === id && r.create);
  if (!row?.value) throw new Error(`no create row for modes/${id} in scripts/data/effect-backfill.json`);
  return row.value as ModeDef;
}
/** A FIELD row amending a record the overlay also creates. A field the create row already carries is
 *  a different row from one added later, and reading the create row alone would miss the later one. */
function overlayField(id: string, field: string): unknown {
  const row = overlayRows().find((r) => r.category === 'modes' && r.id === id && r.field === field);
  if (!row) throw new Error(`no "${field}" row for modes/${id} in scripts/data/effect-backfill.json`);
  return row.value;
}

