/*
 * CONDITIONS — the printed "you are clumsy 1 / encumbered / enfeebled N" half of a mode.
 *
 * Until the engine lane added `ModeDef.conditions` these sentences had no carrier at all, so each one
 * shipped as a note asking the player to open the Conditions panel and do the app's arithmetic by
 * hand. One leg per record, because which record gets which value is the whole finding: a clumsy 1
 * authored on a record whose text prints clumsy 2 is a wrong number, not a missing one.
 */
describe('modes that APPLY the condition their text prints', () => {
  const clumsy1 = (m: ModeDef) => expect(m.conditions).toEqual([{ id: 'clumsy', value: 1 }]);

  it('apricot of bestial might: "You become Clumsy 1"', () => {
    // bug 2026-09-15: modes vs print
    const m = item('item-apricot-of-bestial-might');
    clumsy1(m);
    expect(m.note).not.toContain('apply as a condition');
  });

  it('hydra mutagen: "You are Clumsy 1 for 10 minutes"', () => {
    // bug 2026-09-15: modes vs print
    const m = item('item-hydra-mutagen');
    clumsy1(m);
    expect(m.note).not.toContain('apply as a condition');
  });

  it('giant catch pole: "you are Clumsy 1 while wielding it"', () => {
    // bug 2026-09-15: modes vs print
    const m = mode('item-giant-catch-pole');
    clumsy1(m);
    expect(m.note).not.toContain('apply as a condition');
  });

  it('dinosaur boots: Enlarge makes the wearer clumsy 1', () => {
    // bug 2026-09-15: modes vs print
    // The boots print "the effects of Enlarge"; enlarge (spell-1502's sibling) prints "The creature is
    // Clumsy 1", at 2nd rank and at the 4th-rank heightening alike — so both grades take the same 1.
    const m = item('item-dinosaur-boots');
    clumsy1(m);
    expect(m.note).not.toContain('apply the condition');
  });

  it('dinosaur boots (greater): 4th-rank Enlarge is still clumsy 1', () => {
    // bug 2026-09-15: modes vs print
    clumsy1(item('item-dinosaur-boots-greater'));
  });

  it('convocation of earth and moon: the 4th-rank Enlarge half is clumsy 1', () => {
    // bug 2026-09-15: modes vs print
    const m = mode('aura-convocation-of-earth-and-moon');
    clumsy1(m);
    expect(m.note).not.toContain('apply it as a condition');
  });

  it("curse of the sky's call: enfeebled equals the cursebound value, rung by rung", () => {
    // bug 2026-09-15: modes vs print
    /* Was an it.todo. mystery-15: "you are enfeebled with a value equal to your cursebound value" —
     * four rungs, four values, and authoring 1 on all four would be the failure this leg exists for.
     * These four records live ONLY as overlay create rows, so the `conditions` field is an overlay row
     * of its own (scripts/apply-parity-fixes.mjs), applied after the create. */
    for (const n of [1, 2, 3, 4]) {
      const id = `curse-of-the-skys-call-${n}`;
      expect(`rung ${n}: ${JSON.stringify(overlayField(id, 'conditions'))}`).toBe(
        `rung ${n}: ${JSON.stringify([{ id: 'enfeebled', value: n }])}`,
      );
      expect(overlayMode(id).note).toContain(`enfeebled ${n}`);
    }
  });
});

